(()=>{'use strict';
const D=window.MANEGE,$=s=>document.querySelector(s),main=$('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes=[['dashboard','Dashboard'],['wensen','Stakeholders'],['studio','Ontwerpstudio']];
const nav=$('#nav');nav.innerHTML=routes.map(([id,n])=>`<a href="#${id}">${n}</a>`).join('');
let state={page:'dashboard',params:new URLSearchParams()},lastPage='',lastId='';
const url=(p,params={})=>'#'+p+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
const link=(p,params,label,cl='')=>`<a class="${cl}" href="${esc(url(p,params))}">${label}</a>`;
const tag=(s,cl='')=>`<span class="tag ${cl}">${esc(s)}</span>`;
const typeTag=w=>tag(w.type,w.type==='Eis'?'eis':w.type==='Wens'?'wens':'design');
const ref=(code,passage)=>`<div class="source-ref">${link('bronnen',{source:code},esc(code)+' · '+esc(passage))}</div>`;
const wishRef=w=>ref(w.source,w.time);
const head=(n,t,d)=>`<div class="eyebrow">${esc(n)}</div><h1>${esc(t)}</h1><p class="intro">${esc(d)}</p>`;
const note=t=>`<div class="note">${t}</div>`;
const wishlink=w=>link('wensen',{id:w.id},esc(w.id)+' · '+esc(w.title));
const related=w=>D.wishes.filter(x=>x.org!==w.org&&(x.room===w.room||x.theme===w.theme));
const breadcrumb=()=>`<div class="crumbs"><a href="#dashboard">← Hoofdoverzicht</a><button class="btn" data-back>Vorige weergave</button></div>`;
function wishCard(w){return `<button class="wish" data-wish="${w.id}" aria-pressed="${state.params.get('id')===w.id}"><span class="id">${w.id} · ${esc(w.org)}</span><strong>${esc(w.title)}</strong>${typeTag(w)}<small>${esc(w.theme)} · ${esc(D.rooms[w.room].name)}</small></button>`;}
const noAdvice='Niet besproken door VIA-T: geen specifiek advies over deze gebruikerswens in het interview.';
function adviceBox(ids){return ids.length?ids.map(id=>{const a=D.advice[id];return `<div class="card">${tag(a.type,'advice')}<h3>${esc(a.title)}</h3><p>${esc(a.text)}</p>${ref('V',a.ref.replace(/^V /,''))}<p class="small muted">${esc(a.limits)}</p></div>`}).join(''):`<p class="muted">${noAdvice}</p>`;}
function wishDetail(w,node='wish'){
 const r=D.rooms[w.room],d=D.designs[w.design],matches=related(w),a=w.advice;
 const nodes=[['wish','Bronuitspraak',w.org+' · '+w.id],['need','Ruimtelijke behoefte',w.theme],['room','Functie',r.name],['advice','VIA-T',a.length?'Algemeen aanknopingspunt':'Niet besproken'],['design','Ontwerpvoorstel',d.name]];
 let focus='';
 if(node==='wish')focus=`<h3>${esc(w.title)}</h3><p>${esc(w.detail)}</p>${typeTag(w)}${wishRef(w)}<p class="small muted">Prioriteit: ${w.priority}. Dit is het respondentperspectief; geen formeel projectbesluit.</p>`;
 if(node==='need')focus=`<h3>${esc(w.theme)} · functionele vertaling</h3><p>${esc(w.detail)}</p><h3>Andere organisatie</h3>${matches.length?`<div class="related">${matches.map(wishlink).join('')}</div>`:'<p>Geen rechtstreeks vergelijkbare uitspraak geregistreerd.</p>'}<p class="small muted">Een vergelijkbare functie betekent nog geen identieke eis of instemming met één oplossing.</p>${wishRef(w)}`;
 if(node==='room')focus=`<h3>${esc(r.name)}</h3><p>${esc(r.future)}</p><p><strong>Delen:</strong> ${esc(r.sharing)}</p><p><strong>Voorzieningen:</strong> ${esc(r.facilities)}</p><p><strong>Huidig:</strong> ${esc(r.current)}</p>${link('ruimte',{room:r.id},'Open functieoverzicht →','btn')}${ref('R','§6')}`;
 if(node==='advice')focus=`<h3>VIA-T bij deze behoefte</h3>${a.length?'<p class="small muted">Eigen analytische koppeling met algemeen advies; VIA-T heeft geen ruimtelijke oplossing voor deze wens vastgesteld.</p>':''}<div class="list">${adviceBox(a)}</div>`;
 if(node==='design')focus=`${tag('Eigen ontwerpvoorstel','design')}<h3>${esc(d.name)}</h3><p>${esc(d.text)}</p><p><strong>Nog onbekend:</strong> ${esc(d.unknown)}</p>${ref('R',d.ref.replace(/^R /,''))}<div class="related">${D.wishes.filter(x=>x.design===d.id).map(wishlink).join('')}</div>`;
 return `<section class="detail" aria-label="Gekoppelde onderzoeksinformatie"><div class="id">${w.id} · ${esc(w.org)} · ${esc(w.theme)}</div><h2>${esc(w.title)}</h2><p>${esc(w.detail)}</p><div class="legend">${typeTag(w)}${tag('Prioriteit niet vastgesteld')}${tag('Haalbaarheid onbevestigd','design')}</div><div class="chain" aria-label="Van bronuitspraak naar ontwerpvoorstel">${nodes.map(([id,label,text])=>`<button data-node="${id}" data-id="${w.id}" aria-pressed="${node===id}"><b>${label}</b>${esc(text)}</button>`).join('')}</div><div class="node-detail" id="node-detail" aria-live="polite">${focus}</div><h3>Vergelijkbare behoeften ${w.org==='IVN'?'KNNV':'IVN'}</h3><div class="related">${matches.length?matches.map(wishlink).join(''):'Geen rechtstreeks vergelijkbare uitspraak geregistreerd.'}</div><details><summary>Alle koppelingen en onzekerheden</summary><div><p><strong>Functie:</strong> ${esc(r.name)} — ${esc(r.sharing)}</p><p><strong>VIA-T:</strong> ${a.length?a.map(id=>esc(D.advice[id].title)).join('; ')+' (algemene koppeling, geen inspectie)':noAdvice}</p><p><strong>Ontwerp:</strong> ${esc(d.text)}</p><p><strong>Ontbreekt:</strong> ${esc(r.unknown)}</p>${wishRef(w)}${ref('R',d.ref.replace(/^R /,''))}</div></details></section>`;
}
function dashboard(){return `<section class="hero"><div><div class="eyebrow">De Manege · Onderzoek en ontwerp</div><h1>Samen ruimte geven<br>aan natuur en mensen.</h1><p>Bekijk de behoeften van stakeholders en vertaal het onderzoek naar een bewerkbare indeling van De Manege.</p><a class="btn primary" href="#wensen">Bekijk stakeholders →</a></div><div class="model"><a class="hub" href="#studio">De Manege</a><span class="model-caption">Stakeholders ↔ onderzoeksbehoeften ↔ ruimtelijk ontwerp</span></div></section><div class="two"><a class="card linkcard" href="#wensen"><h2>Stakeholders</h2><p>Bekijk en vergelijk wensen en eisen. Beheerders kunnen stakeholders, gesprekken en gecontroleerde onderzoeksinformatie toevoegen.</p><span class="go">Naar stakeholders →</span></a><a class="card linkcard" href="#studio"><h2>Ontwerpstudio</h2><p>Genereer een indeling op de standaardtekening, teken zelf verder en bewaar ontwerpvarianten.</p><span class="go">Naar ontwerpstudio →</span></a></div><details style="margin-top:24px"><summary>Onderzoeksachtergrond en bestaande koppelingen</summary><div class="related"><a href="#bronnen">Bronnen</a><a href="#vergelijking">Vergelijking</a><a href="#ruimte">Ruimtegebruik</a><a href="#viat">VIA-T</a><a href="#strategie">Ontwerpstrategie</a></div><p class="small">De brongegevens en ontwerpverbanden blijven beschikbaar. VIA-T beschrijft vooral het eigen project; de indelingen zijn conceptuele voorstellen.</p></details>`;}

function filterBar(org=''){
const p=state.params,opt=(values,value)=>'<option value="">Alle</option>'+values.map(v=>`<option ${v===value?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
return `<form class="filters" id="wishfilters"><label>Zoek in wensen<input name="q" type="search" value="${esc(p.get('q')||'')}" placeholder="Bijv. opslag"></label><label>Organisatie<select name="org">${opt(['IVN','KNNV'],org||p.get('org'))}</select></label><label>Thema<select name="theme">${opt([...new Set(D.wishes.map(w=>w.theme))].sort(),p.get('theme'))}</select></label><label>Prioriteit<select name="priority">${opt(['Niet vastgesteld'],p.get('priority'))}</select></label><label>Functie<select name="room">${'<option value="">Alle</option>'+Object.values(D.rooms).map(r=>`<option value="${r.id}" ${p.get('room')===r.id?'selected':''}>${r.name}</option>`).join('')}</select></label><button type="button" class="btn" data-clear>Wis filters</button></form>`;}
function legacyWishes(org=''){
 const p=state.params,actualOrg=p.has('org')?p.get('org'):org,q=(p.get('q')||'').toLocaleLowerCase();let ws=D.wishes.filter(w=>(!actualOrg||w.org===actualOrg)&&(!p.get('theme')||w.theme===p.get('theme'))&&(!p.get('priority')||w.priority===p.get('priority'))&&(!p.get('room')||w.room===p.get('room'))&&JSON.stringify(w).toLocaleLowerCase().includes(q));
 const selected=ws.find(w=>w.id===p.get('id'))||ws[0];
 return head('Wensen en eisen',org?org+' – Wensen en eisen':'Doorzoek alle gebruikersuitspraken',org==='IVN'?'IVN-respondent beschrijft materiaalwerk, educatie en een gedeelde groene plek.':org==='KNNV'?'KNNV-respondent benadrukt determinatie, betaalbaarheid en zelfstandige toegang.':'Selecteer een kaart: alle gekoppelde behoeften, functies, VIA-T-inbreng en ontwerpvoorstellen verschijnen direct.')+filterBar(actualOrg)+`<div class="resultcount" role="status">${ws.length} van ${D.wishes.length} uitspraken · prioriteiten niet formeel gerangschikt</div><div class="layout"><div class="wishlist">${ws.length?ws.map(wishCard).join(''):'<div class="empty">Geen resultaten. Pas de filters aan of wis ze.</div>'}</div><div id="wish-detail">${selected?wishDetail(selected,p.get('node')||'wish'):'<div class="empty">Geen wens geselecteerd.</div>'}</div></div>`;
}
function comparisonNotes(){return `<h2>Nuances die blijven tellen</h2><div class="grid"><div class="card"><h3>Binnen én buiten</h3><p>IVN bespreekt cursussen en nieuwe opstellingen; de KNNV-respondent beschrijft buitenlessen. Geen bewezen tegenstelling. Veertig betreft een IVN-cursus, niet veertig schoolkinderen.</p>${ref('I','07:23–09:52')}${ref('K','13:32–17:30')}</div><div class="card"><h3>Onderhoud versus apparatuur</h3><p>Onderhoud en determinatie passen niet automatisch in dezelfde ruimte. Schoonmaak, geluid en kwetsbaarheid eerst vergelijken.</p>${ref('R','§5.2')}</div><div class="card"><h3>Bedrijven en horeca</h3><p>Gemengd gebruik kan onder voorwaarden. Bescherm verenigingstoegang en stem horeca rechtstreeks met Hortus af.</p>${ref('I','12:43–15:21; 24:23–27:43')}${ref('K','05:57–07:19')}</div></div>`;}
function designCard(d){return `<div>${tag('Eigen ontwerpvoorstel','design')}<h3>${esc(d.name)}</h3><p>${esc(d.text)}</p><p class="small muted">${esc(d.unknown)}</p><div class="related">${D.wishes.filter(w=>w.design===d.id).map(wishlink).join('')}</div>${ref('R',d.ref.replace(/^R /,''))}</div>`;}
function space(){const p=state.params,org=p.get('org')||'',mode=p.get('mode')||'future',available=Object.values(D.rooms).filter(r=>!org||D.wishes.some(w=>w.room===r.id&&w.org===org)),r=available.find(r=>r.id===p.get('room'))||available[0];return head('Ruimtegebruik','De Manege als functioneel netwerk','Geen betrouwbare maatvaste plattegrond beschikbaar. De vakken geven functies weer, geen bestaande kamers, oppervlaktes of definitieve indeling.')+`<div class="filters"><label>Gebruikers<select data-space-org><option value="">Alle stakeholders</option>${window.ManegeResearch.orgs().map(o=>`<option ${org===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label><div class="pills">${link('ruimte',{...Object.fromEntries(p),mode:'current'},'Huidige situatie','btn '+(mode==='current'?'active':''))}${link('ruimte',{...Object.fromEntries(p),mode:'future'},'Mogelijke toekomstige functies','btn '+(mode==='future'?'active':''))}</div></div><div class="layout"><div><div class="schemalabel">Schematisch overzicht · geen schaal</div><div class="roomgrid">${available.map(x=>`<button data-room="${x.id}" class="${x.id===r.id?'active':''}">${esc(x.name)}<small>${mode==='current'?'Huidige informatie beperkt':D.wishes.filter(w=>w.room===x.id&&(!org||w.org===org)).length+' gekoppelde uitspraken'}</small></button>`).join('')}</div><div class="connections">Opslag ↔ werk · opslag ↔ materiaalroute<br>Les ↔ buitenleren · ontvangst ↔ ontmoeting</div>${note(mode==='current'?'Huidige informatie is afkomstig uit projectcontext en respondentbeschrijvingen. Er is geen technische verificatie of ingemeten situatie.':'Mogelijk ontwerp. Geen specifieke stallen, wanden, vloeren of installaties zijn geschikt of herbruikbaar verklaard.')}</div><section class="detail"><div class="eyebrow">${mode==='current'?'Huidige informatie':'Mogelijke functie'}</div><h2>${esc(r.name)}</h2><p>${esc(mode==='current'?r.current:r.future)}</p><p><strong>Gezamenlijk gebruik:</strong> ${esc(r.sharing)}</p><p><strong>Voorzieningen:</strong> ${esc(r.facilities)}</p><h3>Gebruikersuitspraken</h3><div class="related">${D.wishes.filter(w=>w.room===r.id&&(!org||w.org===org)).map(wishlink).join('')}</div><h3>VIA-T</h3>${adviceBox(r.advice)}<h3>Mogelijke ontwerpaanpassing</h3>${designCard(D.designs[r.design])}<p><strong>Ontbreekt:</strong> ${esc(r.unknown)}</p>${ref('R','§6 en §8.2')}</section></div>`;}
function viat(){const p=state.params,phase=Number(p.get('phase')||1),a=D.advice[p.get('advice')]||D.advice.a1;return head('VIA-T','Praktijkervaring als onderzoeksvraag','Eigen pand en verbouwing, hergebruik en praktijkleren. Enkele adviezen zijn gericht op de manege; er is geen technische opname van De Manege uitgevoerd.')+`<div class="grid">${Object.values(D.advice).map(x=>link('viat',{advice:x.id,phase},`<span class="num">${x.id.toUpperCase()} · ${esc(x.type)}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><span class="go">Bekijk onderbouwing →</span>`,'card linkcard')).join('')}</div><div class="detail" style="margin-top:20px">${tag(a.type,'advice')}<h2>${esc(a.title)}</h2><p>${esc(a.text)}</p><p class="quote">${esc(a.evidence)}</p><p><strong>Begrenzing:</strong> ${esc(a.limits)}</p>${ref('V',a.ref.replace(/^V /,''))}<h3>Gekoppelde ontwerpuitgangspunten</h3><div class="related">${Object.values(D.designs).filter(d=>d.advice.includes(a.id)).map(d=>link('strategie',{design:d.id},esc(d.name))).join('')||'Geen directe koppeling aan een specifieke gebruikerswens; algemeen onderzoekscontrolepunt.'}</div></div><h2>Verbouwingsroute in vijf fasen</h2><p class="muted small">De fase-indeling is eigen onderzoeksadvies. De gekoppelde VIA-T-inzichten zijn afzonderlijk herkenbaar. Geen uitvoeringsdata of doorlooptijden vastgesteld.</p><div class="timeline">${D.phases.map(f=>`<a href="${url('viat',{advice:a.id,phase:f.id})}" ${phase===f.id?'aria-current="step"':''}><b>${f.id}</b>${esc(f.name)}</a>`).join('')}</div>${phasePanel(phase)}`;}
function phasePanel(n){const f=D.phases.find(f=>f.id===n)||D.phases[0];return `<div class="detail">${tag('Eigen fasering','design')}<h3>Fase ${f.id} · ${esc(f.name)}</h3><p>${esc(f.action)}</p><p><strong>Beslismoment:</strong> ${esc(f.gate)}</p>${ref('R',f.ref.replace(/^R /,''))}<h3>Relevante inbreng VIA-T</h3><div class="list">${adviceBox(Object.values(D.advice).filter(a=>a.phases.includes(f.id)).map(a=>a.id))}</div>${f.id===5?'<p class="small muted">Voor deze fase is geen specifieke opleverprocedure door VIA-T geadviseerd.</p>':''}</div>`;}
function strategy(){const p=state.params,d=D.designs[p.get('design')||'d1'],ws=D.wishes.filter(w=>w.design===d.id),w=D.wishes.find(w=>w.id===p.get('id'))||ws[0]||D.wishes.find(w=>w.id==='K16');return head('Ontwerpstrategie','Van onderzoeksresultaat naar ontwerpbeslissing','Selecteer een ontwerpuitgangspunt en volg de verbinding terug naar gebruikersuitspraken en bronpassages. Iedere knoop in de keten is klikbaar.')+`<div class="pills">${Object.values(D.designs).map(x=>link('strategie',{design:x.id},esc(x.name),'btn '+(x.id===d.id?'active':''))).join('')}</div><div class="card green"><h3>${esc(d.name)}</h3><p>${esc(d.text)}</p><p class="small">Eigen voorstel · ${esc(d.unknown)}</p></div><div class="layout" style="margin-top:22px"><div><h3>Onderliggende uitspraken</h3><div class="wishlist">${ws.map(wishCard).join('')||'<p>Algemene strategie op basis van K16 en VIA-T-inbreng; geen identieke eis van beide organisaties.</p>'}</div></div><div id="wish-detail">${wishDetail(w,p.get('node')||'design')}</div></div><h2>Wat moet eerst?</h2><div class="grid"><div class="card"><h3>1 · Gebruikers bevestigen</h3><p>Inventaris, werkprocessen, agenda, capaciteit, mandaat en betaalpakket met IVN en KNNV vastleggen.</p></div><div class="card"><h3>2 · Gebouw onderzoeken</h3><p>Meet onderlegger en routes; onderzoek staat, installaties en herbruikbaarheid. Bevestig gebruiksrechten.</p></div><div class="card"><h3>3 · Variant en dekking kiezen</h3><p>Vergelijk basis en groei op functionele dekking, beheer en onderbouwde kosten.</p></div></div>${ref('R','§9.1–9.8')}`;}
function sources(){const p=state.params,q=(p.get('q')||'').toLowerCase(),selected=p.get('source');const ss=Object.values(D.sources).filter(s=>(!selected||s.id===selected)&&JSON.stringify(s).toLowerCase().includes(q));return head('Bronnen','Onderbouwing blijft zichtbaar','De broncode verwijst naar het oorspronkelijke interview of rapport. Tijdcodes zijn indicatieve vindplaatsen, geen opnieuw gecontroleerde woordgrenzen.')+`<form class="filters" id="sourcefilters"><label>Zoek bron<input type="search" name="q" value="${esc(p.get('q')||'')}" placeholder="Titel, organisatie of betrouwbaarheid"></label><button type="button" class="btn" data-all-sources>Alle bronnen</button></form><div class="source-list">${ss.map(s=>`<section class="card"><span class="id">${s.id} · ${esc(s.org)}</span><h2>${esc(s.title)}</h2><p>${esc(s.scope)}</p><p class="small muted">${esc(s.file)} · ${esc(s.date)}</p><p><strong>Beperking:</strong> ${esc(s.limits)}</p>${s.id==='R'?'<p class="small">Het volledige rapport en ruwe interviews zijn niet opgenomen in deze openbare versie.</p>':''}<details><summary>Gekoppelde uitspraken en vindplaatsen</summary><div class="related">${D.wishes.filter(w=>w.source===s.id).map(w=>link('wensen',{id:w.id},`${esc(w.id)} · ${esc(w.title)} · ${esc(w.time)}`)).join('')|| (s.id==='V'?Object.values(D.advice).map(a=>link('viat',{advice:a.id},esc(a.title)+' · '+esc(a.ref))).join(''):'Zie het rapport en de andere bronkaarten.')}</div></details></section>`).join('')||'<div class="empty">Geen bronnen gevonden.</div>'}</div><h2>Wat is wel en niet beschikbaar?</h2><div class="two"><div class="card"><h3>Beschikbaar en onderzocht</h3><p>Volledige IVN-, KNNV- en VIA-T-transcripties; vier projectvisuals; projectmap De Manege; eerdere financierings- en organisatierapporten als context. De eerder gemaakte synthese is de inhoudelijke basis.</p></div><div class="card"><h3>Niet aangetroffen of onbevestigd</h3><p>Een ingemeten/geverifieerde tekening, technische inspectie, getekend gezamenlijk PvE, formele gebruiks- en betaalafspraken en sluitende begroting. Nieuw aangeleverde vectoronderlegger beschikbaar in Ontwerpstudio; binnenindeling en deurposities daarin zijn schattingen. Geen technische haalbaarheid aangetoond.</p></div></div>${note('Eis = noodzakelijk genoemde voorwaarde van een respondent. Wens/voorkeur/idee = andere status. Interpretaties en ontwerpvoorstellen zijn eigen analyse. Automatische transcriptie en ontbrekende respondentvalidatie beperken de bewijskracht. De oorspronkelijke opnamen zijn niet opnieuw integraal beluisterd.')}`;}
const views={studio:()=>window.ManegeStudio.template(),dashboard,ivn:()=>window.ManegeResearch.page(new URLSearchParams({...Object.fromEntries(state.params),org:'IVN'})),knnv:()=>window.ManegeResearch.page(new URLSearchParams({...Object.fromEntries(state.params),org:'KNNV'})),wensen:()=>window.ManegeResearch.page(state.params),vergelijking:()=>window.ManegeResearch.compare(state.params)+comparisonNotes(),ruimte:space,viat,strategie:strategy,bronnen:sources};
function parse(){const hash=location.hash.slice(1)||'dashboard',idx=hash.indexOf('?');let page=idx<0?hash:hash.slice(0,idx),params=new URLSearchParams(idx<0?'':hash.slice(idx+1));if(page==='ivn'||page==='knnv'){if(!params.has('org'))params.set('org',page==='ivn'?'IVN':'KNNV');page='wensen';}if(!views[page])page='dashboard';return {page,params};}
function render(){state=parse();const changed=lastPage!==state.page;nav.querySelectorAll('a').forEach(a=>{if(a.hash==='#'+state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});main.innerHTML=(state.page==='dashboard'?'':breadcrumb())+views[state.page]();if(state.page==='studio')window.ManegeStudio.mount();document.title=(routes.find(r=>r[0]===state.page)?.[1]||'Wensen')+' · De Manege';lastPage=state.page;const id=state.params.get('id');if(changed)window.scrollTo({top:0,behavior:'instant'});else if((id&&id!==lastId)||state.params.get('group')){const panel=document.querySelector('#wish-detail');if(panel)panel.scrollIntoView({block:'start'});}if(!changed&&state.params.get('node'))document.querySelector('[data-node="'+state.params.get('node')+'"]')?.focus({preventScroll:true});lastId=id;}
function update(params,page=state.page){location.hash=url(page,params).slice(1);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-back')){if(history.length>1)history.back();else location.hash='dashboard';}if(b.dataset.wish){let params=Object.fromEntries(state.params);params.id=b.dataset.wish;delete params.node;update(params);}if(b.dataset.node){update({...Object.fromEntries(state.params),id:b.dataset.id,node:b.dataset.node});}if(b.dataset.room){update({...Object.fromEntries(state.params),room:b.dataset.room});}if(b.hasAttribute('data-clear'))update({},state.page);if(b.hasAttribute('data-all-sources'))update({},'bronnen');});
function applyFilters(form){const params=Object.fromEntries(new FormData(form));Object.keys(params).forEach(k=>{if(!params[k]&&k!=='org')delete params[k]});update(params,form.id==='sourcefilters'?'bronnen':(params.org!==undefined&&((state.page==='ivn'&&params.org!=='IVN')||(state.page==='knnv'&&params.org!=='KNNV'))?'wensen':state.page));}
document.addEventListener('change',e=>{const f=e.target.closest('form');if(f)applyFilters(f);if(e.target.matches('[data-space-org]'))update({...Object.fromEntries(state.params),org:e.target.value,room:''});});
let timer;document.addEventListener('input',e=>{if(e.target.id==='global-search'){clearTimeout(timer);const q=e.target.value;timer=setTimeout(()=>update(q?{q}:{},'wensen'),300);}else if(e.target.closest('form')){clearTimeout(timer);const f=e.target.closest('form'),name=e.target.name,start=e.target.selectionStart;timer=setTimeout(()=>{applyFilters(f);setTimeout(()=>{const input=main.querySelector(`[name="${name}"]`);if(input){input.focus();if(input.setSelectionRange&&typeof start==='number')try{input.setSelectionRange(start,start)}catch{}}},0)},250)}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.matches('form'))applyFilters(e.target)});
window.addEventListener('hashchange',render);window.ManegeStore.onChange(()=>{if(!document.getElementById('manage-dialog')?.open)render();});render();window.ManegeStore.start().then(render);document.addEventListener('close',e=>{if(e.target.id==='manage-dialog')render();},true);
})();
